/**
 * A wallet or protocol embedding a Note vault, end to end: discover, verify, quote, deposit with attribution,
 * track, exit.
 *
 *   npm install viem https://note.systems/sdk/note-systems-sdk-0.1.2.tgz
 *   RPC_URL=https://rpc.testnet.chain.robinhood.com PRIVATE_KEY=0x... PARTNER=wallet.example \
 *     npx tsx node_modules/@note-systems/sdk/examples/partner-integration.ts [vault]
 *
 * Without a vault argument the first vault listed by the factory is used. The deposit is 100 quote units (USDG,
 * six decimals). Exits are attempted and, inside the exit lock, the decoded reason is printed instead.
 */
import { createPublicClient, createWalletClient, formatUnits, http, type Address } from 'viem';
import { privateKeyToAccount } from 'viem/accounts';
import { NoteError, createNoteClient, partnerId, robinhoodTestnet } from '@note-systems/sdk';

const rpc = process.env.RPC_URL ?? robinhoodTestnet.rpcUrls.default.http[0];
const key = process.env.PRIVATE_KEY as `0x${string}` | undefined;
if (!key) throw new Error('PRIVATE_KEY is required');
const account = privateKeyToAccount(key);
const publicClient = createPublicClient({ chain: robinhoodTestnet, transport: http(rpc, { batch: true }) });
const walletClient = createWalletClient({ chain: robinhoodTestnet, transport: http(rpc), account });
const note = createNoteClient({ publicClient, walletClient });

const fmt = (x: bigint, d = 6) => formatUnits(x, d);

// 1. Discover: list vaults and read the mandate of each. Nothing here is self reported.
const listed = await note.factory.list(0n, 20n);
console.log(`factory lists ${listed.length} vault(s); bundled vault code matches the pin: ${await note.factory.codeMatches()}`);
const vault = (process.argv[2] as Address | undefined) ?? listed[0];
if (!vault) throw new Error('no vault to use');

// 2. Verify before trusting: the factory must list the vault and its registry must agree with the vault's pointers.
if (!(await note.vaults.verifyBinding(vault))) throw new Error(`${vault} is not a bound vault set from the factory`);
const s = await note.vaults.summary(vault);
console.log(`${s.name} (${s.symbol}) share price ${fmt(s.sharePrice)} USDG, total ${fmt(s.totalAssets)} USDG, idle ${fmt(s.idle)}`);
console.log(`fees ${s.fees.managementBps}/${s.fees.performanceBps} bps, exit lock ${s.limits.exitLock / 3600} h, paused ${s.paused}`);
for (const b of await note.vaults.bands(vault)) {
  console.log(`band ${b.underlying}: barrier ${b.band.minBarrierBps}-${b.band.maxBarrierBps} bps, cap ${fmt(b.band.absoluteCap)} USDG`);
}

// 3. Quote before any signature.
const assets = 100_000_000n; // 100 USDG
const shares = await note.vaults.previewDeposit(vault, assets);
console.log(`previewDeposit(${fmt(assets)}) = ${fmt(shares, 18)} shares; previewRedeem back = ${fmt(await note.vaults.previewRedeem(vault, shares))} USDG`);

// 4. Deposit, attributed to this integrator when its id is registered on the mandate.
const id = partnerId(process.env.PARTNER ?? 'wallet.example');
const registered = await note.vaults.partner(vault, id);
console.log(`partner ${id.slice(0, 10)} ${registered ? `registered, ${registered.shareBps} bps to ${registered.payee}` : 'not registered on this mandate'}`);
if ((await note.vaults.allowance(vault, account.address)) < assets) {
  const a = await note.vaults.approve(vault, assets);
  console.log(`approve ${a.hash} gas ${a.gasUsed}`);
}
const d = await note.vaults.deposit({ vault, assets, receiver: account.address, partnerId: registered ? id : undefined });
console.log(`deposit ${d.hash} minted ${fmt(d.result.shares, 18)} shares, tagged ${d.result.tagged}, gas ${d.gasUsed}`);

// 5. Track: bounded reads, no indexer.
const h = await note.vaults.holding(vault, account.address);
console.log(`holding ${fmt(h.shares, 18)} shares = ${fmt(h.assets)} USDG, partner ${h.partnerId.slice(0, 10)}, unlock ${new Date(h.unlockAt * 1000).toISOString()}`);
for (const e of await note.vaults.exposure(vault)) {
  console.log(`series ${e.seriesId}: ${e.valued ? `value ${fmt(e.quoteValue)} USDG, exposure ${fmt(e.exposure)}` : 'not valued (feed unavailable)'}, settled ${e.settled}`);
}
console.log(`requests: ${(await note.vaults.requests(vault, account.address, 0n, 20n)).length}`);

// 6. Exit: instant against idle liquidity, or through the queue. Inside the lock both revert with Locked.
try {
  const w = await note.vaults.withdraw(vault, assets / 2n, account.address, account.address);
  console.log(`withdraw ${w.hash} gas ${w.gasUsed}`);
  const r = await note.vaults.requestRedeem(vault, h.shares / 4n, account.address, account.address);
  console.log(`requestRedeem ${r.hash} id ${r.result}`);
  const [req] = await note.vaults.requests(vault, account.address, 0n, 1n);
  if (req && req.claimable > 0n) console.log(`claimable ${fmt(req.claimable)} USDG, pending ${fmt(req.pending, 18)} shares`);
} catch (e) {
  if (e instanceof NoteError && e.decoded) console.log(`exit blocked: ${e.decoded.name}: ${e.decoded.message}`);
  else throw e;
}
